        $user = User::inRandomOrder()->first();
        $jobPost = $Posts[$PostIndex++ % count($Posts)];

        $currencyCode = 'USD'; // Default fallback
        $currencyName = ['ar' => 'دولار امريكي', 'en' => 'US Dollar']; // Default fallback

        if ($user->country_id) {
            $country = DB::table('countries')->find($user->country_id);
            if ($country && $country->currency_code) {
                $currencyCode = $country->currency_code;
                $currencyName = json_decode($country->currency_name, true) ?: $currencyName;
            }
        } else {
            // If user has no country, use a random currency
            $randomCurrency = $this->faker->randomElement([
                ['code' => 'ILS', 'name' => ['ar' => 'شيكل', 'en' => 'Shekel']],
                ['code' => 'USD', 'name' => ['ar' => 'دولار امريكي', 'en' => 'US Dollar']],
                ['code' => 'JOD', 'name' => ['ar' => 'دينار اردني', 'en' => 'Jordanian Dinar']],
            ]);
            $currencyCode = $randomCurrency['code'];
            $currencyName = $randomCurrency['name'];
        }

        return [
            'user_id' => $user->id,
            'title' => $jobPost['title'],
            'description' => $jobPost['description'],
            'country_id' => $user->country_id,
            'city_id' => $user->city_id,
            'price' => $this->faker->numberBetween(1, 5000),
            'price_currency_code' => $currencyCode,
            'price_currency_name' => $currencyName,
            'location_latitudes' => fake()->latitude(31.2, 32.5),
            'location_longitudes' => fake()->longitude(34.2, 35.5),
            'type' => $this->faker->randomElement(['عرض', 'طلب']),
            'categories_id' => $jobPost['categories_id'],
            'sub_categories_id' => $jobPost['sub_categories_id'],
        ];
    }

    public function configure(): ServicePostFactory
    {
        return $this->afterCreating(function (ServicePost $servicePost) {
            $usersFav = User::all()->random(10);
            foreach ($usersFav as $user) {
                $favorite = new Favorite();
                $favorite->user_id = $user->id;
                $servicePost->favorites()->save($favorite);
            }
            $servicePost->favorites_count = $servicePost->favorites()->count();
            $servicePost->save();
            $usersReport = User::all()->random(3);
            foreach ($usersReport as $user) {
                $reports = new Report();
                $reports->user_id = $user->id;
                $reports->reason = $this->faker->randomElement(['Spam', 'inappropriate content', 'Harassment', 'false information']);
                $servicePost->reports()->save($reports);
            }
            $servicePost->report_count = $servicePost->reports()->count();
